<?php $items=products($store); ?><section class="page-hero"><div class="container narrow"><p class="eyebrow">Shop</p><h1>Products</h1><p>A small demonstration catalogue showing the reusable storefront, basket and checkout flow. Product data, pricing and stock are configuration-driven.</p></div></section><section class="section"><div class="container"><div class="product-grid"><?php foreach($items as $product):?><article class="product-card"><a class="product-image-link" href="/products/<?=e($product['slug'])?>"><?php if(($image=product_image($store,$product['slug']))!==null):?><img class="product-image" src="<?=e(url($image))?>" alt="<?=e($product['name'])?>" loading="lazy" decoding="async"><?php endif;?></a><p class="eyebrow"><?=e($product['stock'])?> in stock</p><h2><a href="/products/<?=e($product['slug'])?>"><?=e($product['name'])?></a></h2><p><?=e($product['summary'])?></p><p class="price"><?=e(money((int)$product['price_pence'],$store))?></p><div class="actions"><a class="button secondary" href="/products/<?=e($product['slug'])?>">Details</a><form method="post" action="/cart"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="slug" value="<?=e($product['slug'])?>"><button class="button primary" type="submit">Add to basket</button></form></div></article><?php endforeach;?></div></div></section>
